import { secretsFromStoreOnce } from './init/initializeService'
import { sdk } from './sdk'
import {
  postgresDb,
  postgresInitdbArgs,
  postgresMount,
  postgresUser,
} from './utils'

// PostgreSQL as a logical dump (data files are not portable across architectures),
// plus the server data (Django secret, media) and the secret store. The `config`
// volume is regenerated by init on every start.
export const { createBackup, restoreInit } = sdk.setupBackups(async () =>
  sdk.Backups.withPgDump({
    imageId: 'postgres',
    dbVolume: 'db',
    mountpoint: postgresMount,
    pgdataPath: '/data',
    database: postgresDb,
    user: postgresUser,
    initdbArgs: postgresInitdbArgs,
    // Throws when the restored store lacks a valid database password.
    password: async () => (await secretsFromStoreOnce()).dbPassword,
  })
    .addVolume('server')
    .addVolume('startos'),
)
